export interface DispensaryServiceItem {
  id: string;
  sn?: number | string;
  code: string;
  category:
    | 'A: RECEPTION & REGISTRATION'
    | 'B: LABORATORY INVESTIGATION'
    | 'C: CONSULTATION'
    | 'D: RADIOLOGICAL IMAGING'
    | 'E: EYE PROCEDURES'
    | 'F: PROCEDURE'
    | 'G: ADMISSION FEE'
    | 'H: PHARMACY & MEDICATIONS'
    | 'I: MEDICAL SUPPLIES & ORTHOPAEDICS';
  categoryKey:
    | 'reception'
    | 'laboratory'
    | 'consultation'
    | 'radiology'
    | 'eye'
    | 'procedure'
    | 'admission'
    | 'pharmacy_med'
    | 'supplies';
  name: string;
  swahiliName: string;
  officialPrice: number; // in TZS
  sitlReviewPrice?: number; // Counter/negotiated price in TZS if reviewed
  sitlStatus: 'AGREED' | 'REVIEW_PRICE' | 'NOT_COVERED' | 'SPECIFY_REQUIRED';
  sitlNotes?: string;
  coveredByInsurance: boolean;
  departmentScope:
    | 'Laboratory'
    | 'Doctor Office'
    | 'USS'
    | 'OPD/IPD'
    | 'Labour'
    | 'Billing'
    | 'Reception'
    | 'Eye Clinic'
    | 'Pharmacy'
    | 'Store';
}


