/**
 * Split sub-catalogs for targeted department performance
 */
export const CLINICAL_TARIFFS_LIST = OFFICIAL_DISPENSARY_PRICELIST.filter(
  (item) => item.categoryKey !== 'pharmacy_med' && item.categoryKey !== 'supplies'
);

export const PHARMACY_MEDICATIONS_LIST = OFFICIAL_DISPENSARY_PRICELIST.filter(
  (item) => item.categoryKey === 'pharmacy_med' || item.categoryKey === 'supplies'
);

/**
 * High-performance Progressive Matching Search Engine
 * Supports:
 * - Alphabetical direct filter (letter 'A'..'Z')
 * - Progressive prefix and substring matching
 * - Smart rank: prefix > word starts with > contains
 */
export function searchCatalogWithProgressiveMatching(
  items: DispensaryServiceItem[],
  query: string = '',
  selectedLetter: string = '',
  categoryFilter: string = 'All'
): DispensaryServiceItem[] {
  let list = items;

  // 1. Category Filter
  if (categoryFilter !== 'All') {
    list = list.filter((it) => it.categoryKey === categoryFilter || it.category === categoryFilter);
  }

  // 2. Alphabet Filter (A-Z)
  const letter = selectedLetter.toUpperCase().trim();
  if (letter && letter !== 'ALL') {
    list = list.filter((it) => {
      const cleanName = it.name.trim();
      return cleanName.toUpperCase().startsWith(letter);
    });
  }

  // 3. Progressive Search Query
  const q = query.toLowerCase().trim();
  if (!q) {
    // Return sorted alphabetically by name
    return [...list].sort((a, b) => a.name.localeCompare(b.name));
  }

  // Score each item for ranking
  type ScoredItem = { item: DispensaryServiceItem; score: number };
  const scored: ScoredItem[] = [];

  for (const item of list) {
    const nameLower = item.name.toLowerCase();
    const codeLower = item.code.toLowerCase();
    const swahiliLower = item.swahiliName.toLowerCase();

    // Exact prefix match of the whole item name (Highest Rank: 100)
    if (nameLower.startsWith(q) || codeLower.startsWith(q)) {
      scored.push({ item, score: 100 });
      continue;
    }

    // Word prefix match: Any word inside the item name begins with query (Rank: 80)
    const words = nameLower.split(/[\s\[\](),/\-]+/);
    const hasWordPrefix = words.some((w) => w.startsWith(q));
    if (hasWordPrefix) {
      scored.push({ item, score: 80 });
      continue;
    }

    // Substring match in name or swahili name (Rank: 50)
    if (nameLower.includes(q) || swahiliLower.includes(q)) {
      scored.push({ item, score: 50 });
      continue;
    }

    // Code substring match (Rank: 40)
    if (codeLower.includes(q)) {
      scored.push({ item, score: 40 });
      continue;
    }
  }

  // Sort by score DESC, then alphabetically by name ASC
  return scored
    .sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      return a.item.name.localeCompare(b.item.name);
    })
    .map((s) => s.item);
}

/**
 * Fast lookup helper for finding an official service by name, keyword, or code
 */
export function findOfficialService(search: string): DispensaryServiceItem | undefined {
  const q = search.toLowerCase().trim();
  if (!q) return undefined;
  return OFFICIAL_DISPENSARY_PRICELIST.find(
    (s) =>
      s.name.toLowerCase() === q ||
      s.code.toLowerCase() === q ||
      s.name.toLowerCase().includes(q) ||
      s.swahiliName.toLowerCase().includes(q)
  );
}

/**
 * Helper to get exact pricing taking SITL review or insurance status into account
 */
export function getServiceTariffPrice(
  service: DispensaryServiceItem,
  isInsurance: boolean = false
): { price: number; notes?: string } {
  if (isInsurance) {
    if (service.sitlStatus === 'NOT_COVERED') {
      return { price: service.officialPrice, notes: 'Not covered under insurance tariff - Cash only' };
    }
    if (service.sitlReviewPrice) {
      return { price: service.sitlReviewPrice, notes: 'SITL Tariff: TZS ' + service.sitlReviewPrice.toLocaleString() };
    }
  }
  return { price: service.officialPrice, notes: service.sitlNotes };
}

